 "content": "def transform(grid):
    """Copy the non-background tile into every compartment divided by 4-lines."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    div_rows = [r for r in range(h) if all(v == 4 for v in g[r])]
    div_cols = [c for c in range(w) if all(g[r][c] == 4 for r in range(h))]

    def spans(size, divs):
        out = []
        start = 0
        for p in divs:
            if start < p:
                out.append((start, p))
            start = p + 1
        if start < size:
            out.append((start, size))
        return out

    rs, cs = spans(h, div_rows), spans(w, div_cols)
    # The background is the most frequent non-divider color.
    counts = {}
    for row in g:
        for value in row:
            if value != 4:
                counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    source = None
    best = -1
    for r0, r1 in rs:
        for c0, c1 in cs:
            crop = [row[c0:c1] for row in g[r0:r1]]
            n = sum(v != background for row in crop for v in row)
            if n > best:
                best, source = n, crop
    if source is None or best <= 0:
        return g

    for r0, r1 in rs:
        for c0, c1 in cs:
            if r1 - r0 != len(source) or c1 - c0 != len(source[0]):
                continue
            for dr in range(r1 - r0):
                for dc in range(c1 - c0):
                    g[r0 + dr][c0 + dc] = source[dr][dc]
    return g

